        {"구분":"포도주보다 나은 사랑", "내용":"세상 최고의 기쁨보다 뛰어난 사랑의 선언", "그리스도연결":"그리스도의 사랑은 세상의 어떤 것과도 비교할 수 없다 (빌 3:8)"},
        {"구분":"자발적 사랑의 고백", "내용":"신부가 먼저 사랑을 고백하고 구함", "그리스도연결":"우리가 사랑함은 그가 먼저 우리를 사랑하셨음이라 (요일 4:19)"}
