    표8_상담적용: [
        {"상황":"자신에게 좋은 점이 없다고 생각하는 분", "성경원리":"신랑은 신부의 세밀한 부분까지 아름답다고 칭찬한다. 하나님은 우리가 보지 못하는 아름다움을 보신다", "실제적용":"하나님이 주신 은사와 장점을 함께 찾아보고 목록으로 만들어 감사하라"},
        {"상황":"칭찬을 받아들이기 어려운 분", "성경원리":"하나님의 칭찬은 거짓 아첨이 아니라 진실한 사랑에서 나온다. 은혜의 칭찬을 받아들이는 것도 믿음이다", "실제적용":"칭찬을 거부하지 말고 '감사합니다'라고 받아들이는 연습을 하라"},
        {"상황":"외적 치장에만 관심을 쏟는 분", "성경원리":"참된 장식은 외적 장신구가 아니라 내면의 은혜이다. 벧전 3:3-4 '숨은 사람의 마음의 아름다움으로 하라'", "실제적용":"외적 아름다움과 내적 아름다움의 균형을 가르치고, 성령의 열매를 추구하도록 격려하라"}
    ],
