        {"구절":"마 10:30", "연결점":"너희 머리카락까지도 다 세신 바 - 세밀한 돌봄", "구분":"신약"},
        {"구절":"시 139:1-4", "연결점":"여호와여 주께서 나를 살피셨으므로 나를 아시나이다", "구분":"구약"},
        {"구절":"창 24:22", "연결점":"금 고리와 금 팔찌를 주었더라 - 결혼 예물 장신구", "구분":"구약"},
        {"구절":"잠 1:9", "연결점":"네 머리의 아름다운 관이요 네 목의 금 사슬이니라", "구분":"구약"}
