        {"새찬송가":"370", "통일찬송가":"281", "제목":"내 영혼의 그윽히 깊은 데서", "선정이유":"영혼 깊은 곳에서 주님과 교제하는 기쁨"},
        {"새찬송가":"278", "통일찬송가":"233", "제목":"십자가를 질 수 있나", "선정이유":"몰약의 쓴맛처럼 십자가를 기꺼이 지는 헌신"},
        {"새찬송가":"437", "통일찬송가":"332", "제목":"십자가로 가까이", "선정이유":"그리스도와 더 가까이 가려는 갈망"}
