        {"구절":"애 3:22-23", "연결점":"여호와의 인자와 긍휼이 아침마다 새로우니 - 반복되는 사랑", "구분":"구약"},
        {"구절":"시 123:1-2", "연결점":"주인의 손을 바라보는 종의 눈 같이 - 하나님만 바라봄", "구분":"구약"},
        {"구절":"히 12:2", "연결점":"믿음의 주요 또 온전하게 하시는 이인 예수를 바라보자", "구분":"신약"},
        {"구절":"시 119:37", "연결점":"허탄한 것을 보지 말게 하소서 - 순수한 시선", "구분":"구약"},
        {"구절":"창 8:11", "연결점":"비둘기가 감람 새 잎사귀를 물고 돌아옴 - 평화의 비둘기", "구분":"구약"}
