        {"구절":"눅 1:52", "연결점":"비천한 자를 높이셨도다 - 낮은 자의 높임", "구분":"신약"},
        {"구절":"사 57:15", "연결점":"겸손하고 통회하는 자와 함께 거한다 - 낮은 곳의 임재", "구분":"구약"},
        {"구절":"빌 2:6-8", "연결점":"자기를 낮추시고 죽기까지 복종하신 - 그리스도의 겸손", "구분":"신약"},
        {"구절":"왕상 7:19", "연결점":"백합화 형상으로 만든 성전 기둥 장식", "구분":"구약"}
