    표8_상담적용: [
        {"상황":"삶에서 쉼을 찾지 못하는 분", "성경원리":"신부는 사과나무 그늘에 앉아 심히 기뻐했다. 그리스도 안에서 참된 쉼을 찾을 수 있다", "실제적용":"바쁜 일상 중에 하나님의 그늘에 앉는 시간(묵상, 기도, 안식)을 의도적으로 확보하라"},
        {"상황":"하나님의 말씀이 무미건조하게 느껴지는 분", "성경원리":"열매가 달았다는 것은 말씀을 맛보는 경험이다. 시 34:8 '여호와의 선하심을 맛보아 알지어다'", "실제적용":"읽기 방식을 바꿔보라. 빠르게 읽지 말고 한 구절을 천천히 씹으며 묵상하는 렉시오 디비나를 시도하라"},
        {"상황":"세상의 것들에서 만족을 찾으려는 분", "성경원리":"수풀의 나무들은 열매가 없다. 세상의 것들은 진정한 만족을 주지 못한다. 오직 그리스도만이 영혼을 만족시키신다", "실제적용":"세상의 대체물(돈, 성공, 쾌락)로 채우려는 영혼의 빈자리를 그리스도로 채우도록 안내하라"}
    ],
