        {"구절":"요 6:35", "연결점":"나는 생명의 떡이라 - 영혼의 양식", "구분":"신약"},
        {"구절":"갈 6:2", "연결점":"서로 짐을 지라 - 공동체의 도움", "구분":"신약"},
        {"구절":"시 19:7", "연결점":"여호와의 율법은 완전하여 영혼을 소성시키며 - 말씀의 회복력", "구분":"구약"},
        {"구절":"행 2:13", "연결점":"새 술에 취한 것이라 - 성령 충만의 압도감", "구분":"신약"},
        {"구절":"출 33:20", "연결점":"나의 얼굴을 보지 못하리니 - 하나님의 영광의 무게", "구분":"구약"}
