        {"상황":"새로운 사역이나 도전 앞에서 두려운 분", "성경원리":"'함께 가자'는 동행의 약속이다. 혼자 가는 것이 아니라 하나님이 함께 가신다. 수 1:9의 약속을 붙잡으라", "실제적용":"과거에 하나님이 함께하셨던 경험을 기억하며, 새로운 도전에서도 동일한 하나님이 함께하심을 확신하라"}
