    표5_매튜헨리: [
        {"영어원문":"The winter is past, the rain is over and gone — the dark and stormy season of the soul is ended when Christ comes with his comfort.", "한국어번역":"겨울이 지나고 비가 그쳤으니 - 그리스도가 위로를 가지고 오시면 영혼의 어둡고 폭풍치는 계절이 끝난다.", "핵심통찰":"그리스도의 위로가 영혼의 겨울을 끝낸다"},
        {"영어원문":"After the winter of affliction comes the spring of consolation; God never leaves his people in perpetual winter.", "한국어번역":"고난의 겨울 다음에 위로의 봄이 온다. 하나님은 결코 백성을 영원한 겨울에 남겨두지 않으신다.", "핵심통찰":"하나님은 영원한 겨울을 허락하지 않으신다"},
        {"영어원문":"The rain is over and gone — past trials should encourage present faith; if God brought us through the storm, he will bring us into the sunshine.", "한국어번역":"비가 그쳤으니 - 지난 시련이 현재의 믿음을 격려해야 한다. 하나님이 폭풍을 통과시키셨으면 햇빛으로도 인도하실 것이다.", "핵심통찰":"과거의 극복 경험이 현재의 믿음을 강화한다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"겨울도 지나고 - 새 봄이 온다", "예화_적용":"인생에 영원한 겨울은 없다. 봄은 반드시 온다"},
        {"대지":"서론", "내용":"'겨울도 지나고 비도 그쳤고.' 단 두 문장이지만 이 안에 엄청난 희망이 담겨있다. 겨울이 지났다! 비가 그쳤다! 이제 봄이다! 당신의 인생에도 겨울이 있었는가? 그 겨울이 영원할 것 같았는가? 하나님은 선언하신다 - 겨울은 끝났다!", "예화_적용":"가장 긴 겨울밤도 결국 새벽을 맞이한다. 가장 추운 1월도 결국 3월이 된다"},
        {"대지":"1대지: 겨울도 지나고 (시련의 종결)", "내용":"겨울은 시련, 고난, 침체의 시간이다. 그러나 '지나갔다(아바르)' - 완료형이다. 확실히 끝났다. 시 30:5 '저녁에는 울음이 깃들일지라도 아침에는 기쁨이 오리로다'", "예화_적용":"암 투병 끝에 완치 선언을 받았을 때의 기쁨, 장기 실업 끝에 취업했을 때의 감격"},
        {"대지":"2대지: 비도 그쳤고 (눈물의 마침)", "내용":"비는 눈물, 슬픔, 시련의 상징이다. '그쳤다(할라프)' - 완전히 변했다. 계 21:4 '모든 눈물을 그 눈에서 닦아주시니 다시는 사망이 없고 애통하는 것도 없고'", "예화_적용":"오래 울었던 밤이 끝나고 아침 해가 뜨는 순간의 평안"},
        {"대지":"3대지: 이제 봄이다 (새 시대의 시작)", "내용":"12-13절에서 이어지는 봄의 풍경 - 꽃이 피고, 새가 노래하고, 과일이 익는다. 겨울 다음의 봄은 더 아름답다. 고후 5:17 '이전 것은 지나갔으니 보라 새 것이 되었도다'", "예화_적용":"겨울을 겪지 않은 봄보다 혹독한 겨울 다음의 봄이 더 감격적이다"},
        {"대지":"결론", "내용":"지금 겨울에 있는가? 이 말씀을 붙잡으라 - '겨울도 지나고 비도 그쳤고.' 반드시 봄이 온다. 하나님은 영원한 겨울을 허락하지 않으신다. 조금만 더 견디라. 봄이 온다!", "예화_적용":"찰스 스펄전은 우울증의 겨울을 겪으면서 '하나님은 밤을 가져가시고 아침을 가져오신다'고 고백했다"}
    ],
