        {"구절":"사 61:1-3", "연결점":"슬퍼하는 자에게 화관을 주려 하심이라 - 슬픔에서 기쁨으로", "구분":"구약"},
        {"구절":"벧전 1:6-7", "연결점":"여러 가지 시험으로 근심하나 믿음의 시련이 - 시련의 목적", "구분":"신약"}
