        {"영어원문":"The voice of the turtle is heard, the harbinger of spring and love.","한국어번역":"비둘기의 소리가 들리니 봄과 사랑의 전령이다.","핵심통찰":"성령의 음성은 하나님의 사랑이 임하는 전조이다"}
