        {"영어원문":"He is altogether lovely - the summary of all that can be said of Christ.","한국어번역":"그는 모든 것이 사랑스럽다 - 그리스도에 대해 말할 수 있는 모든 것의 요약.","핵심통찰":"그리스도에 대한 최고의 고백은 '모든 것이 사랑스럽다'이다"},
        {"영어원문":"This is my beloved and this is my friend - the best character of Christ.","한국어번역":"이분이 나의 사랑하는 자이며 이분이 나의 친구이다 - 그리스도에 대한 최고의 묘사.","핵심통찰":"그리스도는 사랑의 대상이자 가장 가까운 친구이시다"}
