        {"원어":"אַחַת (아하트)","의미_문법":"하나, 유일한 - 여성 수사. 비교할 수 없는 유일성을 강조","설교포인트":"하나님 앞에서 교회는 유일무이한 사랑의 대상입니다"},
        {"원어":"אִשְּׁרוּהָ (이쉬루하)","의미_문법":"그를 복되다 하다 - 피엘 완료형+3인칭 여성 접미사. 다른 이들이 그녀를 축복하고 칭송함","설교포인트":"하나님의 사랑을 받는 자는 세상으로부터도 인정과 축복을 받게 됩니다"}
