        {"교리":"교회의 이름","설명":"술람밋이 솔로몬의 여성형인 것처럼 교회는 그리스도의 이름을 나누는 존재이다","관련구절":"행 11:26, 엡 3:15"},
        {"교리":"거룩한 기쁨","설명":"마하나임의 춤은 하늘과 땅이 연합하는 거룩한 기쁨과 축제를 상징한다","관련구절":"시 149:3, 삼하 6:14"}
