        {"원어":"נָדִיב (나디브)","의미_문법":"귀한 자, 고귀한 자, 자원하는 자 - 형용사. 왕족의 자녀로서의 신분","설교포인트":"하나님의 자녀는 귀한 왕족의 신분을 가진 존재입니다"},
        {"원어":"חַמּוּקֵי (하무케)","의미_문법":"둥근 곡선, 곡면 - 남성 복수. 보석 세공사가 만든 것처럼 정교한 아름다움","설교포인트":"하나님은 우리를 보석처럼 정교하게 다듬으시는 장인이십니다"}
