        {"항목":"발에서 머리로의 묘사","내용":"4장에서는 머리에서 발로 내려왔지만 7장에서는 발에서 머리로 올라가며 묘사의 방향이 역전된다","목회적활용":"하나님은 우리의 전체를 살피시며 어떤 방향에서도 아름다움을 발견하십니다"}
