        {"원어":"שֵׁן (쉔)","의미_문법":"상아, 이빨 - 남성 단수. 순백색의 귀한 재료로 고급스러움과 순수함을 상징","설교포인트":"그리스도 안에서의 순수함은 가장 귀한 보석보다 가치 있습니다"}
