        {"원어":"נָעַם (나암)","의미_문법":"사랑스러운, 기쁨을 주는 - 칼 완료형. 보는 이에게 기쁨과 쾌감을 주는 아름다움","설교포인트":"성도의 삶이 하나님께 기쁨과 즐거움을 드리는 것이 참된 예배입니다"},
        {"원어":"תַּעֲנוּגִים (타아누김)","의미_문법":"쾌락, 기쁨, 즐거움 - 남성 복수. 깊은 만족과 기쁨의 감정","설교포인트":"하나님은 우리와의 관계에서 깊은 기쁨을 경험하십니다"}
