        {"항목":"세 가지 확인 사항","내용":"싹, 꽃술, 석류꽃 - 성장의 세 단계를 순차적으로 확인하는 세심한 농부의 모습","목회적활용":"영적 성장의 각 단계를 세심하게 살피고 격려하는 것이 필요합니다"},
        {"항목":"포도원에서의 사랑","내용":"'거기서 내 사랑을 주리라'는 사역의 현장이 곧 사랑의 현장임을 보여준다","목회적활용":"사역과 사랑은 분리될 수 없으며 사역의 현장이 사랑을 나누는 곳입니다"}
