        {"항목":"새 것과 옛 것","내용":"새로운 열매와 저장해 둔 오래된 열매를 함께 내놓는 것은 풍성한 대접의 표현","목회적활용":"새로운 은혜와 오랫동안 쌓인 은혜를 모두 하나님께 드리는 것이 참된 헌신입니다"},
        {"항목":"문 앞의 열매","내용":"집 문 앞에 열매를 쌓아 두는 것은 환영과 대접의 준비를 나타낸다","목회적활용":"주님을 맞이하기 위해 항상 준비된 삶을 살아야 합니다"}
