        {"영어원문":"When I should find thee without, I would kiss thee - public profession without shame","한국어번역":"밖에서 만나도 입을 맞추리라 - 부끄러움 없는 공개적 고백","핵심통찰":"그리스도에 대한 사랑은 공개적으로 표현되어야 합니다"},
        {"영어원문":"No one should despise me - freedom from fear of man in expressing love for Christ","한국어번역":"아무도 나를 업신여기지 못하리라 - 그리스도를 향한 사랑 표현에서 사람의 두려움으로부터의 자유","핵심통찰":"사람의 눈이 아닌 하나님의 시선에 집중하는 것이 참된 자유입니다"}
