        {"교리":"사랑의 신적 기원","설명":"여호와의 불(샬헤베트야)이라는 표현은 참된 사랑의 원천이 하나님 자신임을 확언한다","관련구절":"요일 4:8, 요일 4:16"},
        {"교리":"거룩한 질투","설명":"스올같이 잔인한 질투는 하나님의 거룩한 질투를 반영하며 배타적 사랑의 강도를 나타낸다","관련구절":"출 20:5, 출 34:14"}
