        {"원어":"דֶּלֶת (델레트)","의미_문법":"문, 대문 - 여성 단수. 열리고 닫히는 출입구로 불안정한 상태","설교포인트":"아직 흔들리는 신앙에게는 보호와 보강이 필요합니다"}
