        {"항목":"성벽에서 망대로","내용":"8:9에서 성벽이면 은 망대를 세우겠다 했는데 실제로 신부의 유방이 망대가 되었다 - 약속의 성취","목회적활용":"하나님의 약속대로 성장하면 은 망대의 영광이 더해집니다"}
